#include "vsworldmotion.h"
#include <cassert>
int main(){VSWorldMotion motion;VSWorldMotion::Policy policy;LLQuaternion q;q.setQuat(.25f,{0,0,1});assert(motion.accept({1,2,3},q,{4,0,0},{1,0,0},{0,0,1},10));assert(motion.update(10.1,1,true,false,policy));motion.freeze(true);motion.previewPosition({10,20,30});LLQuaternion edit;edit.setQuat(.5f,{0,0,1});motion.previewRotation(edit);assert(motion.timestamp()==10&&motion.selected());assert(!(motion.position()!=LLVector3(10,20,30))&&!(motion.authoritative()!=LLVector3(1,2,3)));assert(!(motion.rotation()!=edit));assert(motion.velocity().mV[0]>4);assert(!motion.update(11,1,true,false,policy));assert(!(motion.position()!=LLVector3(10,20,30)));assert(motion.accept({2,3,4},q,{},{},{},10.5));assert(motion.timestamp()==10.5&&!(motion.position()!=LLVector3(2,3,4)));}
